ValidationRule.errorConditionFormula:
OR(

    AND(
        ISPICKVAL(Paid_By__c, "Traveler"),
        OR(
            ISBLANK(TotalReimbursableAirfare__c),
            NOT(ISBLANK(TotalAirfareCostToState__c))
        )
    ),

    AND(
        OR(
            ISPICKVAL(Paid_By__c, "pCard"),
            ISPICKVAL(Paid_By__c, "Third Party")
        ),
        OR(
            ISBLANK(TotalAirfareCostToState__c),
            NOT(ISBLANK(TotalReimbursableAirfare__c))
        )
    )

)
